def is_cube(n):
    if n < 0:
        return is_cube(-n) and False # Need to handle negative
    return round(n**(1/3))**3 == n

def is_cube_fixed(n):
    root = round(n**(1/3)) if n >= 0 else -round((-n)**(1/3))
    return root**3 == n

def check_range(start, end):
    results = []
    for x in range(start, end):
        val = (8*x - 41) * (x + 3)**2
        if is_cube_fixed(val):
            results.append(x)
    return results

print("Search results -1000 to 1000:", check_range(-1000, 1000))

def get_divisors(n):
    n = abs(n)
    divs = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            divs.append(-i)
            divs.append(n // i)
            divs.append(-(n // i))
    return list(set(divs))

d_values = get_divisors(65)
all_x = set()

for d in d_values:
    # 8b^3 - a^3 = d
    # (2b - a)(4b^2 + 2ab + a^2) = d
    # Let k = 2b - a, so a = 2b - k
    # k(4b^2 + 2b(2b-k) + (2b-k)^2) = d
    # k(4b^2 + 4b^2 - 2bk + 4b^2 - 4bk + k^2) = d
    # k(12b^2 - 6bk + k^2) = d
    # 12b^2 - 6bk + k^2 - d/k = 0

    k_values = get_divisors(d)
    for k in k_values:
        if d % k == 0:
            # Quadratic in b: 12b^2 - 6kb + (k^2 - d/k) = 0
            # b = [6k +/- sqrt(36k^2 - 4*12*(k^2 - d/k))] / 24
            # b = [6k +/- sqrt(36k^2 - 48k^2 + 48d/k)] / 24
            # b = [6k +/- sqrt(48d/k - 12k^2)] / 24

            discriminant = 48 * d / k - 12 * k**2
            if discriminant >= 0:
                root = discriminant**0.5
                if root == int(root):
                    for sign in [-1, 1]:
                        num = 6 * k + sign * int(root)
                        if num % 24 == 0:
                            b = num // 24
                            a = 2 * b - k
                            # Check 8b^3 - a^3 = d
                            if 8 * b**3 - a**3 == d:
                                # u = 65 * b**3 / d
                                if (65 * b**3) % d == 0:
                                    u = (65 * b**3) // d
                                    all_x.add(u - 3)

print("All found x:", sorted(list(all_x)))
